   164	function human_seconds(int $seconds): string
   165	{
   166	  if ($seconds <= 0) {
   167	    return '0 giây';
   168	  }
   169	  if ($seconds < 60) {
   170	    return $seconds . ' giây';
   171	  }
   172	  if ($seconds < 3600) {
   173	    return floor($seconds / 60) . ' phút';
   174	  }
   175	  return floor($seconds / 3600) . ' giờ';
