    31	/**
    32	 * Read admin storage payload.
    33	 *
    34	 * @return array<string,mixed>
    35	 */
    36	function storage_read(): array
    37	{
    38	  $raw = file_get_contents(ADMIN_DATA_PATH);
    39	  if ($raw === false || trim($raw) === '') {
    40	    return [
    41	      'users' => [],
    42	      'login_attempts' => [],
    43	      'audit_logs' => [],
    44	      'meta' => [
    45	        'created_at' => date('c'),
    46	        'updated_at' => date('c'),
    47	      ],
    48	    ];
    49	  }
    50	
    51	  $decoded = json_decode($raw, true);
    52	  if (!is_array($decoded)) {
    53	    return [
    54	      'users' => [],
    55	      'login_attempts' => [],
    56	      'audit_logs' => [],
    57	      'meta' => [
    58	        'created_at' => date('c'),
    59	        'updated_at' => date('c'),
    60	      ],
    61	    ];
    62	  }
    63	
    64	  if (!isset($decoded['users']) || !is_array($decoded['users'])) {
    65	    $decoded['users'] = [];
    66	  }
    67	  if (!isset($decoded['login_attempts']) || !is_array($decoded['login_attempts'])) {
    68	    $decoded['login_attempts'] = [];
    69	  }
    70	  if (!isset($decoded['audit_logs']) || !is_array($decoded['audit_logs'])) {
    71	    $decoded['audit_logs'] = [];
    72	  }
    73	  if (!isset($decoded['meta']) || !is_array($decoded['meta'])) {
    74	    $decoded['meta'] = [];
    75	  }
    76	  if (!isset($decoded['meta']['created_at'])) {
    77	    $decoded['meta']['created_at'] = date('c');
    78	  }
    79	  $decoded['meta']['updated_at'] = date('c');
    80	
    81	  return $decoded;
    82	}
