    84	/**
    85	 * Persist admin storage payload.
    86	 *
    87	 * @param array<string,mixed> $data
    88	 */
    89	function storage_write(array $data): void
    90	{
    91	  $data['meta']['updated_at'] = date('c');
    92	  $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    93	  if ($json === false) {
    94	    throw new RuntimeException('Unable to encode admin storage data.');
    95	  }
    96	  file_put_contents(ADMIN_DATA_PATH, $json . PHP_EOL);
