    99	/**
   100	 * Append audit log to flat log file and storage snapshot.
   101	 *
   102	 * @param array<string,mixed> $record
   103	 */
   104	function append_audit_log(array $record): void
   105	{
   106	  $record['timestamp'] = $record['timestamp'] ?? date('c');
   107	  $record['ip'] = $record['ip'] ?? client_ip();
   108	  $record['user_agent'] = $record['user_agent'] ?? ($_SERVER['HTTP_USER_AGENT'] ?? '');
   109	
   110	  $line = json_encode($record, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
   111	  if ($line !== false) {
   112	    file_put_contents(ADMIN_LOG_PATH, $line . PHP_EOL, FILE_APPEND);
   113	  }
   114	
   115	  $data = storage_read();
   116	  $data['audit_logs'][] = $record;
   117	  if (count($data['audit_logs']) > 500) {
   118	    $data['audit_logs'] = array_slice($data['audit_logs'], -500);
   119	  }
   120	  storage_write($data);
   121	}
