    81	
    82	/**
    83	 * Check lock status for identity and ip.
    84	 *
    85	 * @return array{locked:bool,remaining:int,attempts:int}
    86	 */
    87	function lock_status(string $identity): array
    88	{
    89	  $identity = trim(mb_strtolower($identity));
    90	  $ip = client_ip();
    91	  $now = time();
    92	
    93	  $data = storage_read();
    94	  $attempts = $data['login_attempts'];
    95	  $recent = [];
    96	  foreach ($attempts as $entry) {
    97	    if (!is_array($entry)) {
    98	      continue;
    99	    }
   100	    $entryTime = (int) ($entry['time'] ?? 0);
   101	    if ($entryTime <= 0 || ($now - $entryTime) > ADMIN_LOCK_WINDOW) {
   102	      continue;
   103	    }
   104	    $recent[] = $entry;
   105	  }
   106	
   107	  if (count($recent) !== count($attempts)) {
   108	    $data['login_attempts'] = $recent;
   109	    storage_write($data);
   110	  }
   111	
   112	  $count = 0;
   113	  $oldest = null;
   114	  foreach ($recent as $entry) {
   115	    $entryIdentity = (string) ($entry['identity'] ?? '');
   116	    $entryIp = (string) ($entry['ip'] ?? '');
   117	    if (($identity !== '' && $entryIdentity === $identity) || $entryIp === $ip) {
   118	      $count++;
   119	      if ($oldest === null || (int) $entry['time'] < $oldest) {
   120	        $oldest = (int) $entry['time'];
   121	      }
   122	    }
   123	  }
   124	
   125	  $locked = $count >= ADMIN_LOCK_ATTEMPTS;
   126	  $remaining = 0;
   127	  if ($locked && $oldest !== null) {
   128	    $remaining = max(0, ADMIN_LOCK_WINDOW - ($now - $oldest));
   129	  }
   130	
   131	  return [
   132	    'locked' => $locked,
   133	    'remaining' => $remaining,
   134	    'attempts' => $count,
   135	  ];
   136	}
