   337	}
   338	
   339	/**
   340	 * Verify POST request csrf token and throw user-friendly response when invalid.
   341	 */
   342	function enforce_post_csrf_or_reject(): void
   343	{
   344	  $token = isset($_POST['_csrf_token']) ? (string) $_POST['_csrf_token'] : null;
