--- admin/includes/healthcheck.php
     1	<?php
     2	declare(strict_types=1);
     3	
     4	/**
     5	 * Lightweight CLI healthcheck for Phase 1 auth shell.
     6	 *
     7	 * Usage:
     8	 *   php admin/includes/healthcheck.php
     9	 */
    10	require_once __DIR__ . '/bootstrap.php';
    11	
    12	function health_ok(string $label, bool $ok, string $detail = ''): void
    13	{
    14	  $status = $ok ? 'OK' : 'FAIL';
    15	  echo sprintf("[%s] %s", $status, $label);
    16	  if ($detail !== '') {
    17	    echo ' - ' . $detail;
    18	  }
    19	  echo PHP_EOL;
    20	}
    21	
    22	$checks = [];
    23	
    24	$checks[] = [
    25	  'label' => 'storage directory exists',
    26	  'ok' => is_dir(ADMIN_STORAGE_PATH),
    27	  'detail' => ADMIN_STORAGE_PATH,
    28	];
    29	$checks[] = [
    30	  'label' => 'admin-data.json exists',
    31	  'ok' => file_exists(ADMIN_DATA_PATH),
    32	  'detail' => ADMIN_DATA_PATH,
    33	];
    34	$checks[] = [
    35	  'label' => 'audit.log exists',
    36	  'ok' => file_exists(ADMIN_LOG_PATH),
    37	  'detail' => ADMIN_LOG_PATH,
    38	];
    39	
    40	$data = storage_read();
    41	$hasUsers = isset($data['users']) && is_array($data['users']) && count($data['users']) > 0;
    42	$checks[] = [
    43	  'label' => 'seed user exists',
    44	  'ok' => $hasUsers,
    45	  'detail' => $hasUsers ? 'count=' . count($data['users']) : '',
    46	];
    47	
    48	$hasAuthFns = function_exists('attempt_login') && function_exists('is_authenticated');
    49	$checks[] = [
    50	  'label' => 'auth helpers loaded',
    51	  'ok' => $hasAuthFns,
    52	];
    53	
    54	$allOk = true;
    55	foreach ($checks as $check) {
    56	  $ok = (bool) $check['ok'];
    57	  if (!$ok) {
    58	    $allOk = false;
    59	  }
    60	  health_ok((string) $check['label'], $ok, (string) ($check['detail'] ?? ''));
    61	}
    62	
    63	if (!$allOk) {
    64	  exit(1);
    65	}
    66	
    67	echo PHP_EOL;
    68	echo "Phase 1 healthcheck passed." . PHP_EOL;
    69	echo "Default dev login: admin / admin123" . PHP_EOL;
    70	

