     4	/**
     5	 * Synchronize article index cache from data/articles.json.
     6	 *
     7	 * @return array<string,mixed>
     8	 */
     9	function sync_articles_index(bool $force = false): array
    10	{
    11	  if (!file_exists(ADMIN_ARTICLES_SOURCE_PATH)) {
    12	    return [
    13	      'synced' => false,
    14	      'reason' => 'source_missing',
    15	      'count' => 0,
    16	      'mtime' => 0,
    17	      'cache_updated' => false,
    18	    ];
    19	  }
    20	
    21	  $sourceMTime = (int) (filemtime(ADMIN_ARTICLES_SOURCE_PATH) ?: 0);
    22	  $cache = read_articles_index_cache();
    23	  $cacheMTime = (int) ($cache['meta']['source_mtime'] ?? 0);
    24	
    25	  if (!$force && !empty($cache['items']) && $cacheMTime === $sourceMTime) {
    26	    return [
    27	      'synced' => true,
    28	      'reason' => 'cache_fresh',
    29	      'count' => count($cache['items']),
    30	      'mtime' => $sourceMTime,
    31	      'cache_updated' => false,
    32	    ];
    33	  }
    34	
    35	  $raw = file_get_contents(ADMIN_ARTICLES_SOURCE_PATH);
    36	  if ($raw === false || trim($raw) === '') {
    37	    return [
    38	      'synced' => false,
    39	      'reason' => 'source_empty',
    40	      'count' => 0,
    41	      'mtime' => $sourceMTime,
    42	      'cache_updated' => false,
    43	    ];
    44	  }
    45	
    46	  $decoded = json_decode($raw, true);
    47	  if (!is_array($decoded)) {
    48	    return [
    49	      'synced' => false,
    50	      'reason' => 'source_invalid_json',
    51	      'count' => 0,
    52	      'mtime' => $sourceMTime,
    53	      'cache_updated' => false,
    54	    ];
    55	  }
    56	
    57	  $items = [];
    58	  foreach ($decoded as $item) {
    59	    if (!is_array($item)) {
    60	      continue;
    61	    }
    62	    $normalized = normalize_article_index_item($item);
    63	    if ($normalized !== null) {
    64	      $items[] = $normalized;
    65	    }
    66	  }
    67	
    68	  $cachePayload = [
    69	    'meta' => [
    70	      'source_path' => ADMIN_ARTICLES_SOURCE_PATH,
    71	      'source_mtime' => $sourceMTime,
    72	      'synced_at' => date('c'),
    73	      'count' => count($items),
    74	      'version' => 1,
    75	    ],
    76	    'items' => $items,
    77	    'facets' => build_articles_facets($items),
    78	  ];
    79	  write_articles_index_cache($cachePayload);
    80	
    81	  return [
    82	    'synced' => true,
    83	    'reason' => 'cache_rebuilt',
    84	    'count' => count($items),
    85	    'mtime' => $sourceMTime,
    86	    'cache_updated' => true,
    87	  ];
    88	}
