   180	function normalize_article_index_item(array $item): ?array
   181	{
   182	  $id = trim((string) ($item['id'] ?? ''));
   183	  $title = trim((string) ($item['title'] ?? ''));
   184	  if ($id === '' || $title === '') {
   185	    return null;
