   187	
   188	  $section = trim((string) ($item['section'] ?? ''));
   189	  $libraryKindKey = trim((string) ($item['libraryKindKey'] ?? ''));
   190	  $publishDate = normalize_date_ymd((string) ($item['publishDate'] ?? ''));
   191	  $modifiedDate = normalize_date_ymd((string) ($item['modifiedDate'] ?? ''));
   192	  $topicLv1Key = trim((string) ($item['topicLv1Key'] ?? ''));
   193	  $topicLv2Key = trim((string) ($item['topicLv2Key'] ?? ''));
   194	
   195	  $searchIndex = build_article_search_index([
   196	    $id,
   197	    $title,
   198	    (string) ($item['href'] ?? ''),
   199	    (string) ($item['canonical'] ?? ''),
   200	    (string) ($item['topicLv1Label'] ?? ''),
   201	    (string) ($item['topicLv2Label'] ?? ''),
   202	    (string) ($item['cardTopicLabel'] ?? ''),
   203	    (string) ($item['sectionLabel'] ?? ''),
   204	  ]);
   205	
   206	  $sortDate = $modifiedDate !== '' ? $modifiedDate : $publishDate;
   207	  if ($sortDate === '') {
   208	    $sortDate = '1900-01-01';
   209	  }
   210	
   211	  return [
   212	    'id' => $id,
   213	    'title' => $title,
   214	    'href' => (string) ($item['href'] ?? ''),
   215	    'canonical' => (string) ($item['canonical'] ?? ''),
   216	    'section' => $section,
   217	    'section_label' => (string) ($item['sectionLabel'] ?? ''),
   218	    'library_kind_key' => $libraryKindKey,
   219	    'library_kind_label' => (string) ($item['libraryKindLabel'] ?? ''),
   220	    'topic_lv1_key' => $topicLv1Key,
   221	    'topic_lv1_label' => (string) ($item['topicLv1Label'] ?? ''),
   222	    'topic_lv2_key' => $topicLv2Key,
   223	    'topic_lv2_label' => (string) ($item['topicLv2Label'] ?? ''),
   224	    'publish_date' => $publishDate,
   225	    'modified_date' => $modifiedDate,
   226	    'author_name' => (string) ($item['authorName'] ?? ''),
   227	    'card_badge_label' => (string) ($item['cardBadgeLabel'] ?? ''),
   228	    'search_index' => $searchIndex,
   229	    'sort_date' => $sortDate,
   230	  ];
   231	}
