   233	/**
   234	 * Normalize date to YYYY-MM-DD.
   235	 */
   236	function normalize_date_ymd(string $value): string
   237	{
   238	  $value = trim($value);
   239	  if ($value === '') {
   240	    return '';
   241	  }
   242	
   243	  $time = strtotime($value);
   244	  if ($time === false) {
   245	    return '';
   246	  }
   247	  return date('Y-m-d', $time);
   248	}
