   250	/**
   251	 * Build pre-normalized search index string.
   252	 *
   253	 * @param array<int,string> $parts
   254	 */
   255	function build_article_search_index(array $parts): string
   256	{
   257	  $joined = trim(implode(' ', $parts));
   258	  if ($joined === '') {
   259	    return '';
   260	  }
   261	  $normalized = strtolower($joined);
   262	  $normalized = preg_replace('/\s+/', ' ', $normalized);
   263	  return trim((string) $normalized);
   264	}
