   266	/**
   267	 * Build facets for fast filter select options.
   268	 *
   269	 * @param array<int,array<string,mixed>> $items
   270	 * @return array<string,mixed>
   271	 */
   272	function build_articles_facets(array $items): array
   273	{
   274	  $sections = [];
   275	  $libraryKinds = [];
   276	  $topicLv1 = [];
   277	  $topicLv2 = [];
   278	
   279	  foreach ($items as $item) {
   280	    $sectionKey = (string) ($item['section'] ?? '');
   281	    if ($sectionKey !== '') {
   282	      if (!isset($sections[$sectionKey])) {
   283	        $sections[$sectionKey] = [
   284	          'key' => $sectionKey,
   285	          'label' => (string) ($item['section_label'] ?? $sectionKey),
   286	          'count' => 0,
   287	        ];
   288	      }
   289	      $sections[$sectionKey]['count']++;
   290	    }
   291	
   292	    $kindKey = (string) ($item['library_kind_key'] ?? '');
   293	    if ($kindKey !== '') {
   294	      if (!isset($libraryKinds[$kindKey])) {
   295	        $libraryKinds[$kindKey] = [
   296	          'key' => $kindKey,
   297	          'label' => (string) ($item['library_kind_label'] ?? $kindKey),
   298	          'count' => 0,
   299	        ];
   300	      }
   301	      $libraryKinds[$kindKey]['count']++;
   302	    }
   303	
   304	    $lv1Key = (string) ($item['topic_lv1_key'] ?? '');
   305	    if ($lv1Key !== '') {
   306	      if (!isset($topicLv1[$lv1Key])) {
   307	        $topicLv1[$lv1Key] = [
   308	          'key' => $lv1Key,
   309	          'label' => (string) ($item['topic_lv1_label'] ?? $lv1Key),
   310	          'count' => 0,
   311	        ];
   312	      }
   313	      $topicLv1[$lv1Key]['count']++;
   314	    }
   315	
   316	    $lv2Key = (string) ($item['topic_lv2_key'] ?? '');
   317	    if ($lv2Key !== '') {
   318	      if (!isset($topicLv2[$lv2Key])) {
   319	        $topicLv2[$lv2Key] = [
   320	          'key' => $lv2Key,
   321	          'label' => (string) ($item['topic_lv2_label'] ?? $lv2Key),
   322	          'count' => 0,
   323	        ];
   324	      }
   325	      $topicLv2[$lv2Key]['count']++;
   326	    }
   327	  }
   328	
   329	  $sortFacet = static function (array &$items): void {
   330	    usort($items, static function (array $a, array $b): int {
   331	      return strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
   332	    });
   333	  };
   334	
   335	  $sections = array_values($sections);
   336	  $libraryKinds = array_values($libraryKinds);
   337	  $topicLv1 = array_values($topicLv1);
   338	  $topicLv2 = array_values($topicLv2);
   339	
   340	  $sortFacet($sections);
   341	  $sortFacet($libraryKinds);
   342	  $sortFacet($topicLv1);
   343	  $sortFacet($topicLv2);
   344	
   345	  return [
   346	    'sections' => $sections,
   347	    'library_kinds' => $libraryKinds,
   348	    'topic_lv1' => $topicLv1,
   349	    'topic_lv2' => $topicLv2,
   350	  ];
   351	}
