   353	/**
   354	 * Filter and paginate articles.
   355	 *
   356	 * @param array<string,mixed> $filters
   357	 * @return array<string,mixed>
   358	 */
   359	function query_articles_index(array $filters): array
   360	{
   361	  $cache = read_articles_index_cache();
   362	  $items = is_array($cache['items']) ? $cache['items'] : [];
   363	
   364	  $search = trim(strtolower((string) ($filters['q'] ?? '')));
   365	  $section = trim((string) ($filters['section'] ?? ''));
   366	  $libraryKind = trim((string) ($filters['library_kind_key'] ?? ''));
   367	  $topicLv1 = trim((string) ($filters['topic_lv1_key'] ?? ''));
   368	  $topicLv2 = trim((string) ($filters['topic_lv2_key'] ?? ''));
   369	  $dateFrom = normalize_date_ymd((string) ($filters['date_from'] ?? ''));
   370	  $dateTo = normalize_date_ymd((string) ($filters['date_to'] ?? ''));
   371	  $sort = (string) ($filters['sort'] ?? 'latest');
   372	  $page = max(1, (int) ($filters['page'] ?? 1));
   373	  $perPage = (int) ($filters['per_page'] ?? 20);
   374	  if ($perPage < 10) {
   375	    $perPage = 10;
   376	  }
   377	  if ($perPage > 100) {
   378	    $perPage = 100;
   379	  }
   380	
   381	  $filtered = array_values(array_filter($items, static function ($item) use ($search, $section, $libraryKind, $topicLv1, $topicLv2, $dateFrom, $dateTo): bool {
   382	    if (!is_array($item)) {
   383	      return false;
   384	    }
   385	    if ($search !== '' && strpos((string) ($item['search_index'] ?? ''), $search) === false) {
   386	      return false;
   387	    }
   388	    if ($section !== '' && (string) ($item['section'] ?? '') !== $section) {
   389	      return false;
   390	    }
   391	    if ($libraryKind !== '' && (string) ($item['library_kind_key'] ?? '') !== $libraryKind) {
   392	      return false;
   393	    }
   394	    if ($topicLv1 !== '' && (string) ($item['topic_lv1_key'] ?? '') !== $topicLv1) {
   395	      return false;
   396	    }
   397	    if ($topicLv2 !== '' && (string) ($item['topic_lv2_key'] ?? '') !== $topicLv2) {
   398	      return false;
   399	    }
   400	
   401	    $publishDate = (string) ($item['publish_date'] ?? '');
   402	    if ($dateFrom !== '' && ($publishDate === '' || $publishDate < $dateFrom)) {
   403	      return false;
   404	    }
   405	    if ($dateTo !== '' && ($publishDate === '' || $publishDate > $dateTo)) {
   406	      return false;
   407	    }
   408	
   409	    return true;
   410	  }));
   411	
   412	  usort($filtered, static function (array $a, array $b) use ($sort): int {
   413	    if ($sort === 'oldest') {
   414	      return strcmp((string) ($a['sort_date'] ?? ''), (string) ($b['sort_date'] ?? ''));
   415	    }
   416	    if ($sort === 'title_asc') {
   417	      return strcmp((string) ($a['title'] ?? ''), (string) ($b['title'] ?? ''));
   418	    }
   419	    if ($sort === 'title_desc') {
   420	      return strcmp((string) ($b['title'] ?? ''), (string) ($a['title'] ?? ''));
   421	    }
   422	    return strcmp((string) ($b['sort_date'] ?? ''), (string) ($a['sort_date'] ?? ''));
   423	  });
   424	
   425	  $total = count($filtered);
   426	  $totalPages = max(1, (int) ceil($total / $perPage));
   427	  if ($page > $totalPages) {
   428	    $page = $totalPages;
   429	  }
   430	  $offset = ($page - 1) * $perPage;
   431	  $pageItems = array_slice($filtered, $offset, $perPage);
   432	
   433	  return [
   434	    'items' => $pageItems,
   435	    'meta' => [
   436	      'total' => $total,
   437	      'page' => $page,
   438	      'per_page' => $perPage,
   439	      'total_pages' => $totalPages,
   440	      'offset' => $offset,
   441	    ],
   442	    'filters' => [
   443	      'q' => $search,
   444	      'section' => $section,
   445	      'library_kind_key' => $libraryKind,
   446	      'topic_lv1_key' => $topicLv1,
   447	      'topic_lv2_key' => $topicLv2,
   448	      'date_from' => $dateFrom,
   449	      'date_to' => $dateTo,
   450	      'sort' => $sort,
   451	    ],
   452	    'facets' => is_array($cache['facets']) ? $cache['facets'] : default_articles_facets(),
   453	  ];
   454	}
