   456	/**
   457	 * Find one article item by id.
   458	 *
   459	 * @return array<string,mixed>|null
   460	 */
   461	function find_article_index_item(string $id): ?array
   462	{
   463	  $id = trim($id);
   464	  if ($id === '') {
   465	    return null;
   466	  }
   467	  $cache = read_articles_index_cache();
   468	  foreach ($cache['items'] as $item) {
   469	    if (!is_array($item)) {
   470	      continue;
   471	    }
   472	    if ((string) ($item['id'] ?? '') === $id) {
   473	      return $item;
   474	    }
   475	  }
   476	  return null;
   477	}
