    47	/**
    48	 * @param array<string,mixed> $params
    49	 */
    50	function build_articles_query(array $params): string
    51	{
    52	  $clean = [];
    53	  foreach ($params as $key => $value) {
    54	    if ($value === '' || $value === null) {
    55	      continue;
    56	    }
    57	    if (is_int($value) && $value <= 0) {
    58	      continue;
    59	    }
    60	    $clean[$key] = $value;
    61	  }
    62	  $query = http_build_query($clean);
    63	  return $query === '' ? '' : ('?' . $query);
    64	}
