   137	/**
   138	 * Find matching closing `</div>` offset for div opened at $openOffset.
   139	 */
   140	function find_matching_div_close_offset(string $html, int $openOffset): ?int
   141	{
   142	  $tail = substr($html, $openOffset);
   143	  if ($tail === false || $tail === '') {
   144	    return null;
   145	  }
   146	
   147	  if (!preg_match_all('/<\/?div\b[^>]*>/i', $tail, $tokens, PREG_OFFSET_CAPTURE)) {
   148	    return null;
   149	  }
   150	
   151	  $depth = 0;
   152	  $started = false;
   153	  foreach ($tokens[0] as $entry) {
   154	    $token = strtolower((string) $entry[0]);
   155	    $offset = $openOffset + (int) $entry[1];
   156	    $isClose = str_starts_with($token, '</div');
   157	
   158	    if (!$started) {
   159	      if ($offset !== $openOffset) {
   160	        continue;
   161	      }
   162	      $started = true;
   163	      $depth = 1;
   164	      continue;
   165	    }
   166	
   167	    if ($isClose) {
   168	      $depth--;
   169	      if ($depth === 0) {
   170	        return $offset;
   171	      }
   172	      continue;
   173	    }
   174	
   175	    $depth++;
   176	  }
   177	
   178	  return null;
   179	}
