   217	    'open_tag_end' => $openEnd,
   218	    'close_tag_start' => $closeOffset,
   219	    'end' => $closeOffset + strlen('</script>'),
   220	    'open_tag' => $openTag,
   221	    'close_tag' => '</script>',
