   227	/**
   228	 * Build parser audit report for all indexed articles.
   229	 *
   230	 * @return array<string,mixed>
   231	 */
   232	function run_parser_audit(bool $force = false): array
   233	{
   234	  sync_articles_index(false);
   235	  $cache = read_articles_index_cache();
   236	  $items = is_array($cache['items']) ? $cache['items'] : [];
   237	
   238	  $sourceMTime = file_exists(ADMIN_ARTICLES_SOURCE_PATH) ? (int) filemtime(ADMIN_ARTICLES_SOURCE_PATH) : 0;
   239	  $existing = read_parser_audit_cache();
   240	  $existingMTime = (int) ($existing['meta']['source_mtime'] ?? 0);
   241	
   242	  if (!$force && $existingMTime === $sourceMTime && isset($existing['meta']['safe_count'])) {
   243	    return $existing;
   244	  }
   245	
   246	  $safeCount = 0;
   247	  $fails = [];
   248	  foreach ($items as $article) {
   249	    if (!is_array($article)) {
   250	      continue;
   251	    }
   252	    $path = resolve_article_file_path($article);
   253	    $parsed = parse_article_file($path);
   254	    if (!empty($parsed['ok'])) {
   255	      $safeCount++;
   256	      continue;
   257	    }
   258	    $fails[] = [
   259	      'id' => (string) ($article['id'] ?? ''),
   260	      'href' => (string) ($article['href'] ?? ''),
   261	      'path' => $path,
   262	      'code' => (string) ($parsed['code'] ?? 'unknown'),
   263	      'message' => (string) ($parsed['message'] ?? ''),
   264	    ];
   265	  }
   266	
   267	  $total = count($items);
   268	  $rate = $total > 0 ? round(($safeCount / $total) * 100, 2) : 0.0;
   269	  $report = [
   270	    'meta' => [
   271	      'generated_at' => date('c'),
   272	      'source_mtime' => $sourceMTime,
   273	      'total_count' => $total,
   274	      'safe_count' => $safeCount,
   275	      'fail_count' => count($fails),
   276	      'safe_rate_percent' => $rate,
   277	    ],
   278	    'fails' => $fails,
   279	  ];
   280	
   281	  write_parser_audit_cache($report);
   282	  return $report;
   283	}
   284	
   285	/**
   286	 * Read parser audit cache.
   287	 *
   288	 * @return array<string,mixed>
   289	 */
   290	function read_parser_audit_cache(): array
   291	{
   292	  if (!file_exists(ADMIN_PARSER_AUDIT_PATH)) {
   293	    return [
   294	      'meta' => [
   295	        'generated_at' => '',
   296	        'source_mtime' => 0,
   297	        'total_count' => 0,
   298	        'safe_count' => 0,
   299	        'fail_count' => 0,
   300	        'safe_rate_percent' => 0,
   301	      ],
   302	      'fails' => [],
   303	    ];
   304	  }
   305	
   306	  $raw = file_get_contents(ADMIN_PARSER_AUDIT_PATH);
   307	  if ($raw === false || trim($raw) === '') {
   308	    return [
   309	      'meta' => [
   310	        'generated_at' => '',
   311	        'source_mtime' => 0,
   312	        'total_count' => 0,
   313	        'safe_count' => 0,
   314	        'fail_count' => 0,
   315	        'safe_rate_percent' => 0,
   316	      ],
   317	      'fails' => [],
   318	    ];
   319	  }
   320	
   321	  $decoded = json_decode($raw, true);
   322	  if (!is_array($decoded)) {
   323	    return [
   324	      'meta' => [
   325	        'generated_at' => '',
   326	        'source_mtime' => 0,
   327	        'total_count' => 0,
   328	        'safe_count' => 0,
   329	        'fail_count' => 0,
   330	        'safe_rate_percent' => 0,
   331	      ],
   332	      'fails' => [],
   333	    ];
   334	  }
   335	
   336	  if (!isset($decoded['meta']) || !is_array($decoded['meta'])) {
   337	    $decoded['meta'] = [];
   338	  }
   339	  if (!isset($decoded['fails']) || !is_array($decoded['fails'])) {
   340	    $decoded['fails'] = [];
   341	  }
   342	
   343	  return $decoded;
   344	}
   345	
   346	/**
   347	 * Persist parser audit cache.
   348	 *
   349	 * @param array<string,mixed> $report
   350	 */
   351	function write_parser_audit_cache(array $report): void
   352	{
   353	  $json = json_encode($report, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
   354	  if ($json === false) {
   355	    throw new RuntimeException('Unable to encode parser audit report.');
   356	  }
   357	  file_put_contents(ADMIN_PARSER_AUDIT_PATH, $json . PHP_EOL);
   358	}
   359	
   360	/**
   361	 * Pretty JSON helper for UI rendering.
   362	 *
   363	 * @param array<string,mixed> $payload
   364	 */
   365	function pretty_json(array $payload): string
   366	{
   367	  $json = json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
   368	  return $json === false ? '{}' : $json;
   369	}
