+  if ($title === '') {
+    $errors['title'] = 'Tiêu đề không được để trống.';
+  }
+  $clean['title'] = $title;
+
+  $excerpt = trim((string) ($payload['excerpt'] ?? ''));
+  if ($excerpt === '') {
