    43	  if (!is_array($decoded)) {
    44	    return [
    45	      'meta' => [
    46	        'created_at' => date('c'),
    47	        'updated_at' => date('c'),
    48	        'count' => 0,
    49	      ],
    50	      'drafts' => [],
    51	    ];
    52	  }
    53	
    54	  if (!isset($decoded['meta']) || !is_array($decoded['meta'])) {
    55	    $decoded['meta'] = [];
    56	  }
    57	  if (!isset($decoded['drafts']) || !is_array($decoded['drafts'])) {
    58	    $decoded['drafts'] = [];
    59	  }
    60	
    61	  $decoded['meta']['count'] = count($decoded['drafts']);
    62	  if (!isset($decoded['meta']['updated_at'])) {
