--- admin/includes/healthcheck.php
     1	<?php
     2	declare(strict_types=1);
     3	
     4	/**
     5	 * Lightweight CLI healthcheck for admin shell + article list index.
     6	 *
     7	 * Usage:
     8	 *   php admin/includes/healthcheck.php
     9	 */
    10	require_once __DIR__ . '/bootstrap.php';
    11	
    12	function health_ok(string $label, bool $ok, string $detail = ''): void
    13	{
    14	  $status = $ok ? 'OK' : 'FAIL';
    15	  echo sprintf("[%s] %s", $status, $label);
    16	  if ($detail !== '') {
    17	    echo ' - ' . $detail;
    18	  }
    19	  echo PHP_EOL;
    20	}
    21	
    22	$checks = [];
    23	
    24	$checks[] = [
    25	  'label' => 'storage directory exists',
    26	  'ok' => is_dir(ADMIN_STORAGE_PATH),
    27	  'detail' => ADMIN_STORAGE_PATH,
    28	];
    29	$checks[] = [
    30	  'label' => 'admin-data.json exists',
    31	  'ok' => file_exists(ADMIN_DATA_PATH),
    32	  'detail' => ADMIN_DATA_PATH,
    33	];
    34	$checks[] = [
    35	  'label' => 'audit.log exists',
    36	  'ok' => file_exists(ADMIN_LOG_PATH),
    37	  'detail' => ADMIN_LOG_PATH,
    38	];
    39	$checks[] = [
    40	  'label' => 'articles source exists',
    41	  'ok' => file_exists(ADMIN_ARTICLES_SOURCE_PATH),
    42	  'detail' => ADMIN_ARTICLES_SOURCE_PATH,
    43	];
    44	
    45	$data = storage_read();
    46	$hasUsers = isset($data['users']) && is_array($data['users']) && count($data['users']) > 0;
    47	$checks[] = [
    48	  'label' => 'seed user exists',
    49	  'ok' => $hasUsers,
    50	  'detail' => $hasUsers ? 'count=' . count($data['users']) : '',
    51	];
    52	
    53	$hasAuthFns = function_exists('attempt_login') && function_exists('is_authenticated');
    54	$checks[] = [
    55	  'label' => 'auth helpers loaded',
    56	  'ok' => $hasAuthFns,
    57	];
    58	
    59	$sync = sync_articles_index(false);
    60	$checks[] = [
    61	  'label' => 'articles index cache ready',
    62	  'ok' => !empty($sync['synced']),
    63	  'detail' => 'reason=' . (string) ($sync['reason'] ?? 'unknown') . ', count=' . (string) ($sync['count'] ?? 0),
    64	];
    65	
    66	$audit = run_parser_audit(false);
    67	$checks[] = [
    68	  'label' => 'parser audit ready',
    69	  'ok' => isset($audit['meta']) && is_array($audit['meta']) && isset($audit['meta']['safe_rate_percent']),
    70	  'detail' => 'safe=' . (string) ($audit['meta']['safe_count'] ?? 0) . '/' . (string) ($audit['meta']['total_count'] ?? 0),
    71	];
    72	
    73	$checks[] = [
    74	  'label' => 'draft storage exists',
    75	  'ok' => file_exists(ADMIN_DRAFTS_PATH),
    76	  'detail' => ADMIN_DRAFTS_PATH,
    77	];
    78	
    79	$draftPayload = read_drafts_payload();
    80	$checks[] = [
    81	  'label' => 'draft payload readable',
    82	  'ok' => isset($draftPayload['drafts']) && is_array($draftPayload['drafts']),
    83	  'detail' => 'count=' . (string) count(is_array($draftPayload['drafts'] ?? null) ? $draftPayload['drafts'] : []),
    84	];
    85	
    86	$allOk = true;
    87	foreach ($checks as $check) {
    88	  $ok = (bool) $check['ok'];
    89	  if (!$ok) {
    90	    $allOk = false;
    91	  }
    92	  health_ok((string) $check['label'], $ok, (string) ($check['detail'] ?? ''));
    93	}
    94	
    95	if (!$allOk) {
    96	  exit(1);
    97	}
    98	
    99	echo PHP_EOL;
   100	echo "Phase 4 healthcheck passed." . PHP_EOL;
   101	echo "Default dev login: admin / admin123" . PHP_EOL;

