   400	/**
   401	 * Sync one entry in data/articles.json after publish.
   402	 *
   403	 * @param array<string,mixed> $updates
   404	 */
   405	function sync_article_index_entry(string $articleId, array $updates): void
   406	{
   407	  $articleId = trim($articleId);
   408	  if ($articleId === '' || !file_exists(ADMIN_ARTICLES_SOURCE_PATH)) {
   409	    return;
   410	  }
   411	
   412	  $raw = file_get_contents(ADMIN_ARTICLES_SOURCE_PATH);
   413	  if ($raw === false || trim($raw) === '') {
   414	    return;
   415	  }
   416	  $items = json_decode($raw, true);
   417	  if (!is_array($items)) {
   418	    return;
   419	  }
   420	
   421	  $changed = false;
   422	  foreach ($items as $idx => $item) {
   423	    if (!is_array($item)) {
   424	      continue;
   425	    }
   426	    if ((string) ($item['id'] ?? '') !== $articleId) {
   427	      continue;
   428	    }
   429	    foreach ($updates as $key => $value) {
   430	      $items[$idx][$key] = $value;
   431	    }
   432	    $changed = true;
   433	    break;
   434	  }
   435	
   436	  if (!$changed) {
   437	    return;
   438	  }
   439	
   440	  $json = json_encode($items, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
   441	  if ($json === false) {
   442	    return;
   443	  }
   444	  file_put_contents(ADMIN_ARTICLES_SOURCE_PATH, $json . PHP_EOL);
   445	  sync_articles_index(true);
   446	}
