    15	function build_article_query(array $params): string
    16	{
    17	  $clean = [];
    18	  foreach ($params as $key => $value) {
    19	    if ($value === '' || $value === null) {
    20	      continue;
    21	    }
    22	    if (is_int($value) && $value <= 0) {
    23	      continue;
    24	    }
    25	    $clean[$key] = $value;
    26	  }
    27	  $query = http_build_query($clean);
    28	  return $query === '' ? '' : ('?' . $query);
