    67	/**
    68	 * Validate editable draft payload.
    69	 *
    70	 * @param array<string,mixed> $payload
    71	 * @return array<string,mixed>
    72	 */
    73	function validate_draft_payload(array $payload): array
    74	{
    75	  $errors = [];
    76	  $clean = [];
    77	
    78	  $title = trim((string) ($payload['title'] ?? ''));
    79	  if ($title === '') {
    80	    $errors['title'] = 'Tiêu đề không được để trống.';
    81	  }
    82	  $clean['title'] = $title;
    83	
    84	  $excerpt = trim((string) ($payload['excerpt'] ?? ''));
    85	  if ($excerpt === '') {
    86	    $errors['excerpt'] = 'Mô tả ngắn không được để trống.';
    87	  }
    88	  $clean['excerpt'] = $excerpt;
    89	
    90	  $publishDate = normalize_date_ymd((string) ($payload['publish_date'] ?? ''));
    91	  if ($publishDate === '') {
    92	    $errors['publish_date'] = 'Ngày đăng không hợp lệ.';
    93	  }
    94	  $clean['publish_date'] = $publishDate;
    95	
    96	  $modifiedDateRaw = trim((string) ($payload['modified_date'] ?? ''));
    97	  $modifiedDate = $modifiedDateRaw === '' ? '' : normalize_date_ymd($modifiedDateRaw);
    98	  if ($modifiedDateRaw !== '' && $modifiedDate === '') {
    99	    $errors['modified_date'] = 'Ngày sửa không hợp lệ.';
   100	  }
   101	  if ($modifiedDate === '') {
   102	    $modifiedDate = date('Y-m-d');
   103	  }
   104	  $clean['modified_date'] = $modifiedDate;
   105	
   106	  $tagsInput = trim((string) ($payload['tags_text'] ?? ''));
   107	  $tags = array_values(array_unique(array_filter(array_map(static function (string $part): string {
   108	    return trim($part);
   109	  }, preg_split('/[,;\n]+/', $tagsInput) ?: []), static function (string $value): bool {
   110	    return $value !== '';
   111	  })));
   112	  if (count($tags) < 3) {
   113	    $errors['tags_text'] = 'Cần tối thiểu 3 tag.';
   114	  }
   115	  if (count($tags) > 7) {
   116	    $errors['tags_text'] = 'Tối đa 7 tag.';
   117	  }
   118	  $clean['tags'] = $tags;
   119	  $clean['tags_text'] = implode(', ', $tags);
   120	
   121	  $proseHtml = trim((string) ($payload['prose_html'] ?? ''));
   122	  if ($proseHtml === '') {
   123	    $errors['prose_html'] = 'Nội dung chính không được để trống.';
   124	  }
   125	  $clean['prose_html'] = $proseHtml;
   126	
   127	  return [
   128	    'ok' => empty($errors),
   129	    'errors' => $errors,
   130	    'data' => $clean,
   131	  ];
   132	}
